from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def _error(message: str) -> dict:
    return {"ok": False, "error": message}


def _locate(x: int, y: int, width: int, height: int, cell_size: int, tolerance: int):
    """Map an observation onto a grid cell index, or None if it falls outside."""
    if x < 0 or y < 0:
        return None
    col = x // cell_size
    if col >= width:
        if x - width * cell_size >= tolerance:
            return None
        col = width - 1
    row = y // cell_size
    if row >= height:
        if y - height * cell_size >= tolerance:
            return None
        row = height - 1
    return row, col


def _valid_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    if not isinstance(obs.get("x"), int):
        return False
    if not isinstance(obs.get("y"), int):
        return False
    if not isinstance(obs.get("value"), int):
        return False
    quality = obs.get("quality")
    return isinstance(quality, int) and 0 <= quality <= 100


def _render(sums: dict, counts: dict, degraded: dict, width: int, height: int, fill_value: int) -> tuple:
    """Render the averaged cells and per-cell state flags for the full grid."""
    cells = []
    flags = []
    for row in range(height):
        cell_line = []
        flag_line = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cell_line.append(sums[key] // counts[key])
                flag_line.append("degraded" if key in degraded else "good")
            else:
                cell_line.append(fill_value)
                flag_line.append("empty")
        cells.append(cell_line)
        flags.append(flag_line)
    return cells, flags


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        f"cells={total_cells};filled={filled};dropped={dropped};"
        f"rejected={rejected};saturated={saturated};coverage={coverage}"
    )


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return _error("malformed input")
    if not all(key in raw for key in ("grid", "observations", "fill_value")):
        return _error("missing field")

    grid = raw["grid"]
    observations = raw["observations"]
    fill_value = raw["fill_value"]
    if not isinstance(grid, dict):
        return _error("bad grid")
    if not all(key in grid for key in ("width", "height", "cell_size")):
        return _error("bad grid")

    width = height = cell_size = None
    for name, low, high in (("width", 1, MAX_DIM), ("height", 1, MAX_DIM), ("cell_size", 1, None)):
        value = grid[name]
        if not isinstance(value, int) or value < low or (high is not None and value > high):
            return _error("bad " + name)
        if name == "width":
            width = value
        elif name == "height":
            height = value
        else:
            cell_size = value
    if not isinstance(fill_value, int):
        return _error("bad fill value")
    if not isinstance(observations, list):
        return _error("bad observations")

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if not _valid_observation(obs):
            return _error("bad observation")
        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue
        position = _locate(obs["x"], obs["y"], width, height, cell_size, tolerance)
        if position is None:
            dropped += 1
            continue
        key = position
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells, flags = _render(sums, counts, degraded, width, height, fill_value)
    coverage = len(counts) * 100 // (width * height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }

